import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"中吕·普天乐赠白玉梅","description":"","frontmatter":{"title":"中吕·普天乐赠白玉梅","date":"2026-11-11T00:00:00.000Z","seq":33,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·普天乐赠白玉梅.md","filePath":"blogs/元曲·张可久/中吕·普天乐赠白玉梅.md"}'),o={name:"blogs/元曲·张可久/中吕·普天乐赠白玉梅.md"};function l(c,a,n,m,z,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·普天乐赠白玉梅" tabindex="-1">中吕·普天乐赠白玉梅 <a class="header-anchor" href="#中吕·普天乐赠白玉梅" aria-label="Permalink to &quot;中吕·普天乐赠白玉梅&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">谪仙名，乐天姓。</p><p class="poem-stanza">缁尘不染，玉骨长清。</p><p class="poem-stanza">西楼羌管声，东阁新诗兴。</p><p class="poem-stanza">艳紫妖红尘俗病，论风流让与琼琼。</p><p class="poem-stanza">孤山旧盟，黄昏月明，夜雪初晴。</p><p class="poem-stanza">别怀二首故人疏，忧心悄。</p><p class="poem-stanza">愁云淡淡，远水迢迢。</p><p class="poem-stanza">一声白雁寒，几点青山小。</p><p class="poem-stanza">满目凄凉谁知道？赋情词写遍芭蕉。</p><p class="poem-stanza">明月洞箫，夕阳细草，沙渚残潮。</p><p class="poem-stanza">梦初回，愁难禁。</p><p class="poem-stanza">青楼痛饮，彩扇新吟。</p><p class="poem-stanza">金莲小步移，玉藕香腮枕。</p><p class="poem-stanza">惜雨怜云别图甚？五百年一对知音。</p><p class="poem-stanza">别离动心，分明为您，憔悴如今。</p><p class="poem-stanza">客怀楚山云，湘江岸。</p><p class="poem-stanza">霜添白发，日减朱颜。</p><p class="poem-stanza">秋风马耳寒，夜雪貂裘绽。</p><p class="poem-stanza">万里南归孤飞雁，动离情故国乡关。</p><p class="poem-stanza">闲身易懒，休官怕晚，倦羽知还。</p><p class="poem-stanza">收心二首姓名香，行为俏。</p><p class="poem-stanza">花花草草，暮暮朝朝。</p><p class="poem-stanza">关心三月春，开口千金笑。</p><p class="poem-stanza">惜玉怜香何时了，彩云空声断鸾箫。</p><p class="poem-stanza">朱颜易老，青山自好，白发难饶。</p><p class="poem-stanza">旧行头，家常扮。</p><p class="poem-stanza">鸳鸯被冷，燕子楼拴。</p><p class="poem-stanza">偷将心事传，掇了梯儿看。</p><p class="poem-stanza">系柳监花乔公案，关防的不似今番。</p><p class="poem-stanza">姨夫暗攒，行院斗侃，子弟先&lt;走山&gt;。</p><p class="poem-stanza">秋怀为谁忙？莫非命。</p><p class="poem-stanza">西风驿马，落月书灯。</p><p class="poem-stanza">青天蜀道难，红叶吴江冷。</p><p class="poem-stanza">两字功名频看镜，不饶人白发星星。</p><p class="poem-stanza">钓鱼子陵，思莼季鹰，笑我飘零。</p><p class="poem-stanza">道情北邙烟，西州泪。</p><p class="poem-stanza">先朝故家，破冢残碑。</p><p class="poem-stanza">樽前有限杯，门外无常鬼。</p><p class="poem-stanza">未冷鸳帏合欢被，画楼前玉碎花飞。</p><p class="poem-stanza">悔之晚矣，蒲团纸被，归去来兮。</p><p class="poem-stanza">渡扬子江凤鸾吟，鱼龙竞。</p><p class="poem-stanza">舟移古渡，潮打空城。</p><p class="poem-stanza">清风江上筝，明月波心镜。</p><p class="poem-stanza">未尽诗人登临兴，写新声寄与卿卿。</p><p class="poem-stanza">金山雪晴，玉杯露冷，银海花生。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
